"""Render D251 fixed-gate results; never selects a new model or criterion."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2];OUT=ROOT/'reports/d251_critic_gate'
def main():
 result=json.loads((OUT/'result.json').read_text());p=json.loads((OUT/'protocol.json').read_text());fit=json.loads((OUT/'fit.json').read_text())
 assert result['passed']==all(result['criteria'].values())
 lines=['# D251: repaired critic and fixed final test','',f"Overall: **{'PASS — authorized bounded AWS pilot may proceed' if result['passed'] else 'FAIL — do not start AWS'}**.",'','This verdict uses exactly the criteria saved before model selection and the six new test flights. No thresholds were added or changed after the test. No second fit or extra test seeds were used.','', '## Criteria','', '| Criterion | Result |', '|---|---|']
 for k,v in result['criteria'].items():lines.append(f"| {k} | {'PASS' if v else 'FAIL'} |")
 lines+=['','The complete numerical conditions are in CRITERIA.md and protocol.json.','', '## Repair and separation','', 'The original critic nearly interpolated two flights. The replacement uses the same linear head and frozen VLA context features, with flight-balanced ridge regularization selected by leave-one-whole-flight-out validation on all five previously inspected D250 flights. These are development flights only. The selected alpha is '+str(fit['cv']['selected_alpha'])+'. The checkpoint was locked before the final test. No action-model parameter was trained.', '', 'Six new local simulator flights used seeds101/102 on the three declared numeric tasks (turn, vertical descent, steep descent). No reference test benchmark was used. Terminal episodes supply measured Monte Carlo targets; horizons are reported and excluded from uncensored-return metrics.', '', '## Independent prediction and signal results','',f"Terminal flights: {result['terminal_flights']}/6; successful stops: {result['successes']}; failed stops: {result['failed_stops']}; premature endpoint/heading stops: {result['premature_stops']}.",'',f"Equal-flight MSE: {result['mse']}; zero baseline: {result['zero_baseline_mse']}; development-mean baseline: {result['training_mean_baseline_mse']}.",'',f"Terminal MAE: {result['terminal_mae']}; worst terminal error: {result['terminal_max_error']}.",'', '| Flight | Completion | Critic value | Actual terminal return | Raw stop credit |','|---|---|---:|---:|---:|']
 for row in result['terminals']:lines.append(f"| {row['flight']} | {row['complete']} | {row['value']:.4f} | {row['target']:.4f} | {row['advantage']:.4f} |")
 lines+=['','State and continuation checks: '+json.dumps(result['state_rates'])+'.','','Advantage scale: '+json.dumps(result['advantage_scale'])+'.','','## Integrity and limitations','',f"Actor frozen: {result['actor_frozen']}; actor updates:0; exact context overlap:{result['exact_context_overlap']}; maximum first-token probability replay error:{result['first_token_max_error']}. All values and raw arrays were finite; loaded critic predictions match exactly. All57 local tests and9 reward controls passed; three additional initial-critic import tests passed. The optional training entry point now accepts --initial-critic and disables fresh warmup only for that explicit path; default training is unchanged.",'','The state stop-now check uses a constructed stationary continuation at a real measured state, not a second physically flown branch. It tests measured-return-minus-value, not unknown intermediate-value GAE for that hypothetical branch. Actual terminal and continuation results use recorded model actions. Six local flights qualify only this bounded learning-signal pilot, not general flight improvement or other movement kinds.','', '## Decision','']
 if result['passed']:
  lines+=['Proceed under the already authorized two-hour AWS cap, same NF4 policy/reward, four actor updates, matched turn/altitude comparison, then stop for review. Ordinary artifact/replay/KL/frozen/reload operational guards remain those stated upfront. No additional research conditions.']
 else:
  lines+=['AWS remains unstarted because these original criteria failed: '+', '.join(result['failed'])+'. No automatic refit, new seed search, relaxed threshold or cloud retry. The repaired critic is preserved as a failed candidate. This is a fixed-gate failure, not a pass followed by a new condition.']
 (OUT/'REPORT.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
 print(lines[2])
if __name__=='__main__':main()
